def solve_M(a):
    n = len(a)
    a_1based = [0] + a
    f = [-float('inf')] * (n + 1)
    if n >= 2:
        f[2] = a_1based[1] + a_1based[2]
    if n >= 3:
        f[3] = a_1based[3] + max(f[2], a_1based[1], a_1based[2])
    for i in range(4, n + 1):
        f[i] = a_1based[i] + max(f[i-1], f[i-2], a_1based[i-1], a_1based[i-2])
    max_sum = 1
    for i in range(1, n + 1):
        max_sum = max(max_sum, f[i])
    return max_sum

